<script>
 import { tick } from 'svelte';
 import { bytesFromFile } from './disk-image-codec.js';
 import './disk-native.css';
 let { state: nativeTimeMachineState, windowId, profile, controller, execute, registerView } = $props();
 let root = $state(), scroller = $state(), feedback = $state(''), folderId = $state(null), destinationRootId = $state('');
 let session = $derived(nativeTimeMachineState.sessions.find(row => row.windowId === windowId));
 let windows = $derived(profile.id.startsWith('windows'));
 let classic = $derived(/high-sierra|mojave/.test(profile.id));
 let wallpaperURL = $derived(controller.getDesktopWallpaperURL());
 let backup = $derived.by(() => { void nativeTimeMachineState; void session; return controller.getBackupStatus(); });
 let snapshots = $derived([...nativeTimeMachineState.snapshots].sort((a,b) => b.createdAt - a.createdAt));
 let snapshot = $derived(snapshots.find(row => row.id === session?.snapshotId));
 let availability = $derived(snapshot ? controller.getSnapshotAvailability(snapshot.id) : null);
 let snapshotIndex = $derived(snapshots.findIndex(row => row.id === session?.snapshotId));
 let historical = $derived.by(() => { void nativeTimeMachineState; void session; return snapshot ? controller.getSnapshotFiles(snapshot.id) : []; });
 let selected = $derived(historical.find(row => row.sourceFileId === session?.selectedId));
 let query = $derived((session?.search ?? '').trim().toLocaleLowerCase('en-US'));
 let shown = $derived(historical.filter(row => query ? [row.name,row.mime,row.sourceFileId].some(value => String(value ?? '').toLocaleLowerCase('en-US').includes(query)) : folderId === null ? row.parentSourceId === snapshot?.sourceRootId || row.parentSourceId === null : row.parentSourceId === folderId));
 let currentFolder = $derived(historical.find(row => row.sourceFileId === folderId));
 let preview = $derived.by(() => { if (!selected || selected.kind === 'folder') return null; const mime = selected.mime ?? '', textual = /^text\//.test(mime) || /^(application\/(json|xml|javascript)|image\/svg\+xml)$/.test(mime) || (!mime && selected.encoding === 'utf8'); try { const bytes = bytesFromFile(selected); let imageSource = null; if (/^image\/(png|jpeg|gif|webp|bmp)$/u.test(mime)) { let binary = ''; for (let offset = 0; offset < bytes.length; offset += 8192) binary += String.fromCharCode(...bytes.subarray(offset, offset + 8192)); imageSource = `data:${mime};base64,${btoa(binary)}`; } return { bytes: bytes.byteLength, text: textual ? new TextDecoder('utf-8', { fatal: true }).decode(bytes) : null, imageSource, error: '' }; } catch (error) { return { bytes: null, text: null, imageSource: null, error: error.message }; } });
 let collisionSheet = $derived(session?.panel === 'collision');
 const authoredDate = instant => new Date(instant).toLocaleString('en-US', { timeZone: 'UTC', year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', second: '2-digit' }) + ' UTC';
 let backupRunning = $derived(backup.status === 'preparing' || backup.status === 'backing-up');
 async function send(command, payload = {}) { try { const result = await execute(command, { windowId }, payload); feedback = result?.status === 'rejected' ? result.error?.message ?? 'The backup operation could not be completed.' : ''; return result; } catch (error) { feedback = error.message; } }
 function restore(collision = 'ask') { const payload = { collision }; if (destinationRootId) payload.destinationRootId = destinationRootId; return send('timeMachine.restore', payload); }
 function openFolder(file) { folderId = file.sourceFileId; void send('timeMachine.select', { fileId: file.sourceFileId }); }
 $effect(() => { void session?.snapshotId; folderId = null; });
 $effect(() => { if (collisionSheet) void tick().then(() => root?.querySelector('[data-time-control="collision-cancel"]')?.focus()); });
 function sheetKeys(event) { if (event.key === 'Escape') { event.preventDefault(); void send('timeMachine.cancel'); } if (event.key === 'Tab') { const controls = [...event.currentTarget.querySelectorAll('button')].filter(node => !node.disabled); if (event.shiftKey && event.target === controls[0]) { event.preventDefault(); controls.at(-1)?.focus(); } else if (!event.shiftKey && event.target === controls.at(-1)) { event.preventDefault(); controls[0]?.focus(); } } }
 $effect(() => {
  const original = root, originalScroller = scroller, originalSession = session; if (!original || !originalScroller || !originalSession) return;
  let retired = false;
  const available = () => !retired && root === original && scroller === originalScroller && original.isConnected && nativeTimeMachineState.sessions.find(row => row.windowId === windowId) === originalSession;
  const find = (attribute, id) => [...original.querySelectorAll(`[${attribute}]`)].find(node => node.getAttribute(attribute) === id && node.getClientRects().length && !node.disabled && !node.closest('[inert]'));
  const reject = () => ({ status: 'rejected', error: { code: 'stale_target', message: 'The original mounted Time Machine view is unavailable.' } });
  const view = { available, describe: () => available() ? { windowId, controlIds: [...original.querySelectorAll('[data-time-control]')].map(node => node.dataset.timeControl), areaIds: ['files','timeline','preview'] } : null,
   async focus(target, guard = () => true) { const controlId = typeof target === 'string' ? target : target.controlId, node = find('data-time-control', controlId); if (!available() || guard() !== true || !node) return reject(); node.focus(); await tick(); return available() && guard() === true && find('data-time-control', controlId) === node && node.ownerDocument.activeElement === node ? { status: 'applied', controlId } : reject(); },
   async scroll({ areaId = 'files', top = 0, left = 0 }, guard = () => true) { const node = find('data-time-area', areaId); if (!available() || guard() !== true || !node) return reject(); node.scrollTo({ top, left, behavior: 'instant' }); await tick(); return available() && guard() === true && find('data-time-area', areaId) === node ? { status: 'applied', areaId, top: node.scrollTop, left: node.scrollLeft } : reject(); }, destroy() { retired = true; } };
  const unregister = registerView(windowId, view); return () => { view.destroy(); if (typeof unregister === 'function') unregister(); };
 });
</script>

{#if session}
<section bind:this={root} class="disk-native time-machine" class:disk-classic={classic} class:disk-windows={windows} style:--time-wallpaper={windows || !wallpaperURL ? 'none' : `url(${JSON.stringify(wallpaperURL)})`} aria-label={windows ? 'Time Machine local equivalent' : 'Time Machine'}>
 {#if windows}<p class="disk-disclosure">Functional local Time Machine equivalent, not Windows File History. Backups and restores use actual scene Files only.</p>{:else if profile.id.includes('golden-gate')}<p class="disk-disclosure">macOS 27 Time Machine appearance is unverified; nearest macOS 26-inspired presentation.</p>{/if}
 <div class="time-backup-status" inert={collisionSheet}><span class="time-machine-clock" aria-hidden="true">↶</span><div><strong>{backup.status}</strong><small>{backup.destinationRootId ? `Backup destination: ${backup.volumes.find(row => row.rootFileId === backup.destinationRootId)?.name ?? backup.destinationRootId}` : 'No backup destination selected in backup settings'}</small><small>{backup.automatic ? 'Automatic backups enabled' : 'Automatic backups off'} · {backup.excludedFileIds.length} excluded items</small></div><button data-time-control="backup-now" disabled={!backup.destinationRootId || backupRunning} onclick={() => send('backup.now')}>Back Up Now</button><button data-time-control="backup-cancel" disabled={!backupRunning} onclick={() => send('backup.cancel')}>Cancel Backup</button></div>
 <div class="time-universe" inert={collisionSheet}>
  <div class="time-stack">
   {#each snapshots.slice(Math.max(0,snapshotIndex) + 1, Math.max(0,snapshotIndex) + 4).reverse() as past, index}<div class="time-history-card" style:--time-layer={3-index} aria-hidden="true"><header>{authoredDate(past.createdAt)}</header><p>{past.files.length} saved entries</p></div>{/each}
   <section class="time-finder" aria-label="Historical Finder window">
    <header class="time-finder-toolbar"><div class="time-folder-navigation"><button data-time-control="folder-up" disabled={!folderId || !!query} aria-label="Go to enclosing historical folder" onclick={() => folderId = currentFolder?.parentSourceId === snapshot?.sourceRootId ? null : currentFolder?.parentSourceId ?? null}>‹</button><button data-time-control="folder-root" disabled={!snapshot} onclick={() => folderId = null}>Backup Root</button></div><strong>{query ? 'Search Results' : currentFolder?.name ?? 'Backup Files'}</strong><label class="time-search"><span aria-hidden="true">⌕</span><input data-time-control="search" aria-label="Search historical file metadata" placeholder="Search" value={session.search} oninput={event => send('timeMachine.search', { query: event.currentTarget.value })}/></label></header>
    <div class="time-finder-body"><aside class="time-finder-sidebar"><h2>Favorites</h2><button class:chosen={!folderId} data-time-control="favorites-root" disabled={!snapshot} onclick={() => folderId = null}>All Backup Files</button>{#each historical.filter(row => row.kind === 'folder' && row.parentSourceId === snapshot?.sourceRootId) as folder}<button class:chosen={folderId === folder.sourceFileId} data-time-control={`folder:${folder.sourceFileId}`} onclick={() => openFolder(folder)}>{folder.name}</button>{/each}<h2>Snapshot</h2><p>{snapshot ? authoredDate(snapshot.createdAt) : 'No backup selected'}</p></aside>
     <div class="time-file-table" bind:this={scroller} data-time-area="files" tabindex="0"><table><thead><tr><th>Name</th><th>Kind</th><th>Revision</th></tr></thead><tbody>{#each shown as file}<tr class:chosen={selected?.sourceFileId === file.sourceFileId}><td><button data-time-control={`file:${file.sourceFileId}`} aria-pressed={selected?.sourceFileId === file.sourceFileId} onclick={() => send('timeMachine.select', { fileId: file.sourceFileId })} ondblclick={() => file.kind === 'folder' && openFolder(file)}><span class:time-folder-icon={file.kind === 'folder'} class:time-document-icon={file.kind !== 'folder'} aria-hidden="true"></span>{file.name}</button></td><td>{file.kind === 'folder' ? 'Folder' : file.mime ?? 'Document'}</td><td>{file.revision}</td></tr>{/each}</tbody></table>{#if !snapshot}<div class="disk-empty"><h2>No backup selected</h2><p>{snapshots.length ? 'Choose a date on the timeline to browse the actual historical Files.' : 'No snapshots are available. Choose a backup destination in backup settings, then use Back Up Now.'}</p></div>{:else if !shown.length}<p class="time-empty">{query ? 'No historical metadata matches your search.' : 'This historical folder has no available entries.'}</p>{/if}</div>
     <aside class="time-preview" data-time-area="preview" tabindex="0" aria-label="Historical file preview">{#if selected}<h2>{selected.name}</h2>{#if selected.kind === 'folder'}<p>Historical folder</p><p>{historical.filter(row => row.parentSourceId === selected.sourceFileId).length} direct available entries</p><button data-time-control="open-folder" onclick={() => openFolder(selected)}>Open Folder</button>{:else if preview?.imageSource}<img class="time-historical-image" style="max-width:100%;max-height:240px;object-fit:contain" src={preview.imageSource} alt={`Historical ${selected.name}`} onerror={event => { if (event.currentTarget.isConnected && event.currentTarget.getAttribute('src') === preview?.imageSource) feedback = 'The actual historical image bytes could not be decoded.'; }} />{:else if preview?.text !== null && preview?.text !== undefined}<pre>{preview.text}</pre>{:else}<div class="time-binary-preview"><span class="time-document-icon" aria-hidden="true"></span><p>Binary or non-text document</p><p>No visual decoder is available for this format.</p>{#if preview?.error}<p class="disk-error" role="alert">The saved content could not be decoded: {preview.error}</p>{/if}</div>{/if}<dl class="time-file-metadata"><dt>Original ID</dt><dd>{selected.sourceFileId}</dd><dt>Backup file ID</dt><dd>{selected.backupFileId}</dd><dt>Format</dt><dd>{selected.mime || 'Not specified'}</dd><dt>Encoding</dt><dd>{selected.encoding ?? 'Not specified'}</dd><dt>Revision</dt><dd>{selected.revision}</dd>{#if selected.kind !== 'folder'}<dt>Actual content bytes</dt><dd>{preview?.bytes?.toLocaleString('en-US') ?? 'Unavailable'}</dd>{/if}</dl>{:else}<p>Select a historical file to preview its actual saved content and metadata.</p>{/if}</aside>
    </div>
    <footer class="time-finder-status">{shown.length} visible entries{availability?.available === false ? ` · Backing version unavailable: ${availability.message}` : snapshot && historical.length !== snapshot.files.length ? ` · ${snapshot.files.length - historical.length} saved entries unavailable or changed` : ''}</footer>
   </section>
  </div>
  <aside class="time-timeline" data-time-area="timeline" tabindex="0" aria-label="Backup timeline"><h2>Backups</h2>{#each snapshots as saved}<button class:chosen={snapshot?.id === saved.id} data-time-control={`snapshot:${saved.id}`} aria-pressed={snapshot?.id === saved.id} onclick={() => send('timeMachine.snapshot', { snapshotId: saved.id })}><span class="time-timeline-tick" aria-hidden="true"></span><time datetime={new Date(saved.createdAt).toISOString()}>{authoredDate(saved.createdAt)}</time><small>{saved.files.length} entries</small></button>{/each}{#if !snapshots.length}<p>No saved dates</p>{/if}</aside>
 </div>
 <footer class="time-machine-footer" inert={collisionSheet}><div class="time-history-navigation"><button data-time-control="newer" disabled={snapshotIndex <= 0} onclick={() => send('timeMachine.snapshot', { snapshotId: snapshots[snapshotIndex-1].id })}>↑ Newer</button><button data-time-control="older" disabled={snapshotIndex < 0 || snapshotIndex >= snapshots.length-1} onclick={() => send('timeMachine.snapshot', { snapshotId: snapshots[snapshotIndex+1].id })}>↓ Older</button></div><div class="time-restore-target"><label>Restore to<select data-time-control="destination" bind:value={destinationRootId}><option value="">Original location</option>{#each backup.volumes.filter(row => row.mounted && row.rootFileId !== backup.destinationRootId) as volume}<option value={volume.rootFileId}>{volume.name}</option>{/each}</select></label><button data-time-control="cancel" onclick={() => send('timeMachine.cancel')}>{session.stage === 'running' ? 'Cancel Restore' : 'Cancel'}</button><button class="disk-default" data-time-control="restore" disabled={!selected || session.stage === 'running'} onclick={() => restore('ask')}>Restore</button></div></footer>
 {#if session.stage === 'running'}<div class="time-restore-progress"><progress value={session.progress} max="100" aria-label="Time Machine restore progress"></progress><span>{session.progress}%</span></div>{/if}
 <p class="time-message" role="status">{feedback || session.message || (snapshot ? authoredDate(snapshot.createdAt) : 'Choose a backup date')}</p>
 {#if collisionSheet}<div class="disk-sheet-shade"><section class="disk-sheet" role="dialog" aria-modal="true" aria-label="Resolve restore collision" tabindex="-1" onkeydown={sheetKeys}><h2>A file with the same name already exists.</h2><p>Restoring “{selected?.name ?? 'the selected item'}” conflicts with a file in the destination. Choose how to handle existing names.</p><p class="disk-warning">Replace permanently discards existing destination content. Keep Both preserves the existing file and creates a separate restored copy.</p><div class="disk-actions disk-collision-actions"><button data-time-control="collision-cancel" onclick={() => send('timeMachine.cancel')}>Cancel</button><button data-time-control="collision-skip" onclick={() => restore('skip')}>Skip Existing</button><button data-time-control="collision-keep" onclick={() => restore('keepBoth')}>Keep Both</button><button class="disk-default" data-time-control="collision-replace" onclick={() => restore('replace')}>Replace</button></div>{#if feedback}<p class="disk-error" role="alert">{feedback}</p>{/if}</section></div>{/if}
</section>
{/if}
